tion class="card mt-5"><table class="data-table w-full"><thead><tr><th>#</th><th>Name</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach($tables as $t):?><tr><td><?=$t['table_number']?></td><td><?=sanitize($t['table_name'])?></td><td><?=sanitize($t['table_type'])?></td><td><?=sanitize($t['status'])?></td></tr><?php endforeach?></tbody></table></section><?php elseif($tab==='rates'):?><form method="post" class="card mt-5"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="action" value="rate"><div class="grid md:grid-cols-3 gap-3"><input class="input" name="plan_name" required placeholder="Plan name"><select class="input" name="billing_type"><option value="per_minute">Per Minute</option><option value="per_frame">Per Frame</option><option value="slab">Slab</option><option value="challenge">Challenge Only</option></select><input class="input" type="number" name="rate_per_minute" step=".01" min="0" placeholder="Rs. per minute"><input class="input" type="number" name="rate_per_frame" step=".01" min="0" placeholder="Rs. per frame"><input class="input" type="number" name="slab_minutes" min="1" value="60" placeholder="Slab up to minutes"><input class="input" type="number" name="slab_price" min="0" value="700" placeholder="Slab price"><input class="input" type="number" name="extra_minutes" min="1" value="15" placeholder="Extra minutes"><input class="input" type="number" name="extra_price" min="0" value="100" placeholder="Extra price"></div><button class="btn-primary mt-4">Save Rate Plan</button></form><section class="card mt-5"><table class="data-table w-full"><thead><tr><th>Plan</th><th>Type</th><th>Per Min</th><th>Per Frame</th></tr></thead><tbody><?php foreach($plans as $p):?><tr><td><?=sanitize($p['plan_name'])?></td><td><?=sanitize($p['billing_type'])?></td><td><?=money($p['rate_per_minute'])?></td><td><?=money($p['rate_per_frame'])?></td></tr><?php endforeach?></tbody></table></section><?php else:?><section class="card mt-5 max-w-2xl"><h2 class="font-bold">TV Display</h2><p class="text-slate-400 text-sm mt-2">Share this tokenised link with your in-club TV. It does not need staff login.</p><input class="input mt-4" readonly value="<?=url('tv.php?token='.$c['tv_token'])?>"><form method="post" class="mt-4"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="action" value="token"><button class="btn-danger">Regenerate TV Token</button></form></section><?php endif?><?php require __DIR__.'/../includes/footer.php'; ?>
